head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.v_SaveKind = ""; // 신규,수정 구분
scwin.vBzProcsNo = ""; // 업무처리번호
scwin.vIsuCd = ""; // 종목코드
scwin.vDscYn = ""; // 공시여부
// 화면ID
// var vIsurCd = "";                    //발행기관코드
// var vIsurNm = "";                    //발행회사명

// Transaction 처리코드
scwin.TR_JOB;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name canUploadFile
 * @description 2017-02-13 KBoY FileSizeLimit 30MB
 * @returns {void}
 * @hidden N
 */
scwin.canUploadFile = function() {
    const maxFileSize = 1024 * 1024 * 30; // 30MB
    const mySize = inf_find.FileInfo('size');
    if (mySize < maxFileSize) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name filedown
 * @description 파일 다운로드 (gubun = 311) (Params : bzProcsNo:업무처리번호 , attachFileNo: 번호)
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} attachSeq attachSeq
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function(bzProcsNo, attachSeq) {
    location.href = "/filedownload.do?SCREN_ID=" + "ULDSTF70030_N.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&BZ_PROCS_NO=" + bzProcsNo + "&ATTACH_SEQ=" + attachSeq + "&gubun=311";
};

/**
 * @method
 * @name fileSync
 * @description 첨부파일 리스트 불러오기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileSync = async function() {
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_fileList",
        action : "/digital/DigitalListinvstg.do",
        ref : "",
        target : "dts_fileList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name checkForm
 * @description Form Validation Check
 * @param {*} kind kind
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function(kind) {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (edt_CHG_LIST_DD.getValue() === "") {
        await $c.win.alert("[변경상장일]을 입력하세요.");
        edt_CHG_LIST_DD.focus();
        return false;
    }

    // Check Max Length
    if (txb_ISU_NM2.getValue() !== "") {
        if (Number($c.stf.getStringSize(txb_ISU_NM2.getValue())) > 1) {
            if (!$c.stf.checkMaxLength(txb_ISU_NM2, 80, "한글종목명")) return false;
        }
    } else if (txb_ISU_NM2.getValue() === "") {
        await $c.win.alert("[한글종목명]을 입력하세요.");
        txb_ISU_NM2.focus();
        return false;
    }
    if (txb_ISU_ABBRV2.getValue() !== "") {
        if (Number($c.stf.getStringSize(txb_ISU_ABBRV2.getValue())) > 1) {
            if (!$c.stf.checkMaxLength(txb_ISU_ABBRV2, 40, "한글종목약명")) return false;
        }
    } else if (txb_ISU_ABBRV2.getValue() === "") {
        await $c.win.alert("[한글종목약명]을 입력하세요.");
        txb_ISU_ABBRV2.focus();
        return false;
    }
    if (txb_ISU_ENG_NM2.getValue() !== "") {
        if (Number($c.stf.getStringSize(txb_ISU_ENG_NM2.getValue())) > 1) {
            if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM2, 80, "영문종목명")) return false;
        }
    } else if (txb_ISU_ENG_NM2.getValue() === "") {
        await $c.win.alert("[영문종목명]을 입력하세요.");
        txb_ISU_ENG_NM2.focus();
        return false;
    }
    if (txb_ISU_ENG_ABBRV2.getValue() !== "") {
        if (Number($c.stf.getStringSize(txb_ISU_ENG_ABBRV2.getValue())) > 1) {
            if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV2, 40, "영문종목약명")) return false;
        }
    } else if (txb_ISU_ENG_ABBRV2.getValue() === "") {
        await $c.win.alert("[영문종목약명]을 입력하세요.");
        txb_ISU_ENG_ABBRV2.focus();
        return false;
    }

    // 병합 비율
    if (txb_DIGITAL_SECU_CONSLDT_RTO.getValue() === "") {
        txb_DIGITAL_SECU_CONSLDT_RTO.setValue("0");
    }

    // 분할 비율
    if (txb_DIGITAL_SECU_SPLIT_RTO.getValue() === "") {
        txb_DIGITAL_SECU_SPLIT_RTO.setValue("0");
    }

    // 증권 수
    if (txb_LIST_QTY2.getValue() === "") {
        txb_LIST_QTY2.setValue("0");
    }

    // 신규인 경우에만 체크하도록 함
    if (scwin.v_SaveKind === "N") {
        if (vCurDate >= edt_CHG_LIST_DD.getValue()) {
            await $c.win.alert("[변경상장일]을 현재일이후로 입력하세요.");
            edt_CHG_LIST_DD.focus();
            return false;
        }
    }

    // 변경사유 길이체크
    if (!$c.stf.checkMaxLength(txa_CHG_RSN, 2000, "변경사유")) return false;
    return true;
};

/**
 * @method
 * @name setFormField
 * @description 신규저장,수정하기 전 Form Field Value에 대하여 2바이트 체크 (현업의 미입력에서도 '-' 하이픈을 입력하는 경우가 많아 처리함)
 * @returns {void}
 * @hidden N
 */
scwin.setFormField = function() {
    if (Number($c.stf.getStringSize(txb_ISU_NM2.getValue())) === 1) {
        txb_ISU_NM2.setValue("");
    }
    if (Number($c.stf.getStringSize(txb_ISU_ABBRV2.getValue())) === 1) {
        txb_ISU_ABBRV2.setValue("");
    }
    if (Number($c.stf.getStringSize(txb_ISU_ENG_NM2.getValue())) === 1) {
        txb_ISU_ENG_NM2.setValue("");
    }
    if (Number($c.stf.getStringSize(txb_ISU_ENG_ABBRV2.getValue())) === 1) {
        txb_ISU_ENG_ABBRV2.setValue("");
    }
};

/**
 * @method
 * @name dupCheck
 * @description 종목 중복날짜 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dupCheck = async function() {
    const chgDd = edt_CHG_LIST_DD.getValue();
    let isNotDup = true;
    dts_DupChk.removeAll();
    const sbmOptions = {
        id : "sbm_dts_DupChk",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_DupChk=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (dts_DupChk.getRowCount() > 0) {
        if (scwin.vBzProcsNo !== dts_DupChk.getCellData(1, "BZ_PROCS_NO")) {
            isNotDup = false;
            await $c.win.alert("동일한 날짜에 변경상장 지정된 종목이 존재합니다.");
        }
    }
    return isNotDup;
};

/**
 * @method
 * @name selectIsur
 * @description 신규 내역 조회
