    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    //    vIsurCd= dts_Isu.NameValue(1,"ISUR_CD");
    //    vIsurNm = dts_Isu.NameValue(1,"ISUR_NM");

};

/**
 * @method
 * @name saveNmIsurNew
 * @description 변경상장 > 종목명변경/증권분할.병합입력 및 세부내역 > 신규저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveNmIsurNew = async function() {
    // if (fn_CheckForm(v_SaveKind) == false)
    //    return;

    scwin.TR_JOB = 'I';
    if (await scwin.checkForm(scwin.v_SaveKind) && await scwin.dupCheck()) {
        // Transaction 처리전 안내문구
        if (!$c.lcd.fn_isProcess(scwin.TR_JOB)) return;

        // 저장 처리
        let vScrenId = "SCREN_ID=" + "ULDSTF70030_N.xml";
        let vScrenTpId = "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        let vSrvMethod = "&method=insertNmChngDtl";
        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo); // 업무처리번호 새로 지정

        trs_Save.KeyName = "toinb_dataid4";
        // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     TRS_IDX : TR_JOB_INSERT,
        //     LIST_BZ_TP_CD : scwin.vListBzTpCd,
        //     BZ_PROCS_NO : scwin.vBzProcsNo,
        //     ISU_CD : scwin.vIsuCd,
        //     ISUR_CD : dts_Isu.getCellData(1, "ISUR_CD"),
        //     ACPT_NO : js_emp_no,
        //     LD_MKT_TP_CD : "1",
        //     TRANSTR_EMP_NO : js_emp_no
        // };
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/digital/DigitalListinvstg.do",
            ref : "dts_Isu,dts_fileList",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name saveNmIsurUpdate
 * @description 변경상장 > 종목명변경  > 상세보기 > 수정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveNmIsurUpdate = async function() {
    scwin.TR_JOB = 'U';
    if (($c.cp.isModified(dts_Isu) === false) && ($c.cp.isModified(dts_fileList) === false)) {
        await $c.win.alert("수정내역이 존재하지 않습니다.");
        return;
    }
    if (await scwin.checkForm(scwin.v_SaveKind) && await scwin.dupCheck()) {
        // Transaction 처리전 안내문구
        if (!$c.lcd.fn_isProcess(scwin.TR_JOB)) return;
        if ($c.ut.trim(txb_LIST_QTY2.getValue()) === "") {
            txb_LIST_QTY2.setValue("0");
        }
        let vScrenId = "SCREN_ID=" + "ULDSTF70030_N.xml";
        let vScrenTpId = "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        let vSrvMethod = "&method=updateNmChngDtl";
        trs_Save.KeyName = "toinb_dataid4";
        // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     TRS_IDX : TR_JOB_UPDATE,
        //     LIST_BZ_TP_CD : scwin.vListBzTpCd,
        //     BZ_PROCS_NO : scwin.vBzProcsNo,
        //     ISU_CD : scwin.vIsuCd,
        //     ISUR_CD : dts_Isu.getCellData(1, "ISUR_CD"),
        //     LD_MKT_TP_CD : "1",
        //     ACPT_NO : js_emp_no,
        //     TRANSTR_EMP_NO : js_emp_no
        // };
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/digital/DigitalListinvstg.do",
            ref : "dts_Isu,dts_fileList",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name saveNmIsurDelete
 * @description 변경상장 > 종목명 변경 > 상세보기 > 삭제
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveNmIsurDelete = async function() {
    if (scwin.vBzProcsNo === "") {
        await $c.win.alert("삭제 정보(업무처리번호)가 없습니다.");
        return;
    }

    // 공시 체크
    if (!$c.lcd.fn_check_delete_discls(dts_BzProcsNo, scwin.vBzProcsNo)) return;
    scwin.TR_JOB = 'D';

    // Transaction 처리전 안내문구
    if (!$c.lcd.fn_isProcess(scwin.TR_JOB)) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    let vScrenId = "SCREN_ID=" + "ULDSTF70030_N.xml";
    let vScrenTpId = "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    let vSrvMethod = "&method=deleteNmChngDtl";
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : TR_JOB_DELETE,
    //     LIST_BZ_TP_CD : scwin.vListBzTpCd,
    //     BZ_PROCS_NO : scwin.vBzProcsNo,
    //     ISU_CD : scwin.vIsuCd,
    //     ISUR_CD : dts_Isu.getCellData(1, "ISUR_CD"),
    //     LD_MKT_TP_CD : "1",
    //     ACPT_NO : js_emp_no,
    //     TRANSTR_EMP_NO : js_emp_no
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/digital/DigitalListinvstg.do",
        ref : "dts_Isu",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name checkModifyDts
 * @description 안내문작성 시, 수정사항 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkModifyDts = async function() {
    let rtn = false;
    if ($c.cp.isModified(dts_Isu) === false) {
        rtn = true;
    } else {
        await $c.win.alert("변경된 내용이 있습니다. [수정] 후 진행하세요.");
        rtn = false;
    }
    return rtn;
};

/**********************************************
 * 함수명 : fn_dscl()
 * 설명    : 수량변경 > 발행 및 상장내역 > 안내문 작성
 ***********************************************/
scwin.getPar, scwin.setPar;

/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    if (edt_CHG_LIST_DD.getValue() === "") {
        await $c.win.alert("[변경상장일]을 입력하세요.");
        edt_CHG_LIST_DD.focus();
        return false;
    }
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    const cCtnt = "";
    if (await scwin.checkModifyDts() === false) {
        return;
    }
    scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2) {
        arr[0] = "69565A";
        arr[1] = scwin.vBzProcsNo;
        arr[2] = dts_Isu.getCellData(1, "ISUR_CD"); // 상장신청인 발행코드
        arr[3] = '1';
        // arr[4] = fn_getNmChgDisclsCtnt(); //ctnt
        arr[5] = txb_ISU_ABBRV.getValue(); // add  title

        const sDate = scwin.dateForm(edt_CHG_LIST_DD.getValue());
        $c.stf.copyDataSet(dts_Isu, param_dts_isu);
        $c.stf.copyDataSet(dts_Isu, param_dts_mst);

        // 파라미터 ds 만 값 변경
        param_dts_isu.setCellData(param_dts_isu.getFocusedRowIndex(), "CHG_LIST_DD", sDate);
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "CHG_LIST_DD", sDate);
        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    const wth = 750;
    const hgt = 820;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "변경상장 종목명변경/증권분할·분할 안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;

    // 안내문팝업 후 '닫기'나 '안내문전송' 후에 Popup Close 및 Parent Refresh 함
    $c.frame.path("../").fn_list_nm_chglist_sync();
};

/**
 * @method
 * @name getNmChgDisclsCtnt
 * @description 안내문작성 서식 (수량변경)
 * @returns {void}
 * @hidden N
 */
scwin.getNmChgDisclsCtnt = function() {
    let vIsuNmChg = ""; // 종목명변경 Y/N
    let vIsuQtyChg = ""; // 수량변경 Y/N

    if (txb_ISU_NM2.getValue().length > 0 || txb_ISU_ABBRV2.getValue().length > 0 || txb_ISU_ENG_NM2.getValue().length > 0 || txb_ISU_ENG_ABBRV2.getValue().length > 0) {
        vIsuNmChg = "Y";
    } else {
        vIsuNmChg = "N";
    }
    if ((txb_DIGITAL_SECU_CONSLDT_RTO.getValue().length > 0 || txb_DIGITAL_SECU_SPLIT_RTO.getValue().length > 0 || txb_LIST_QTY2.getValue().length > 0) &&
        (txb_DIGITAL_SECU_CONSLDT_RTO.getValue() > 0 || txb_DIGITAL_SECU_SPLIT_RTO.getValue() > 0 || txb_LIST_QTY2.getValue() > 0)) {
        vIsuQtyChg = "Y";
    } else {
        vIsuQtyChg = "N";
    }
    let vCtnt;
    vCtnt = "[공시제목] 신종증권 변경상장";
    vCtnt += "\r\n\r\n";
    vCtnt += "[본문내용]";
    vCtnt += "\r\n\r\n";
    vCtnt += "◎ " + txb_ISU_NM.getValue() + " 변경상장";
    vCtnt += "\r\n\r\n";
    vCtnt += "\r\n\r\n";
    vCtnt += "1. 변경내역  ";
    if (vIsuNmChg === "Y") {
        vCtnt += "\r\n\r\n";
        vCtnt += " - 한글종목명";
        vCtnt += "\r\n\r\n";
        vCtnt += "변경전 : " + txb_ISU_NM.getValue() + " (약명 : " + txb_ISU_ABBRV.getValue() + ")";
        vCtnt += "\r\n\r\n";
        vCtnt += "변경후 : " + txb_ISU_NM2.getValue() + " (약명 : " + txb_ISU_ABBRV2.getValue() + ")";
        vCtnt += "\r\n\r\n";
        vCtnt += " - 영문종목명";
        vCtnt += "\r\n\r\n";
        vCtnt += "변경전 : " + txb_ISU_ENG_NM.getValue() + " (약명 : " + txb_ISU_ENG_ABBRV.getValue() + ")";
        vCtnt += "\r\n\r\n";
        vCtnt += "변경후 : " + txb_ISU_ENG_NM2.getValue() + " (약명 : " + txb_ISU_ENG_ABBRV2.getValue() + ")";
    }
    if (vIsuQtyChg === "Y") {
        vCtnt += "\r\n\r\n";
        vCtnt += " - 병합·분할";
        vCtnt += "\r\n\r\n";
        vCtnt += "병합비율 : " + txb_DIGITAL_SECU_CONSLDT_RTO.getValue();
        vCtnt += "\r\n\r\n";
        vCtnt += "분할비율 : " + txb_DIGITAL_SECU_SPLIT_RTO.getValue();
        vCtnt += "\r\n\r\n";
        vCtnt += "변경전 상장수량 : " + txb_LIST_QTY.getValue();
        vCtnt += "\r\n\r\n";
        vCtnt += "변경후 상장수량 : " + txb_LIST_QTY2.getValue();
    }
    vCtnt += "\r\n\r\n";
    vCtnt += "2. 변경 사유 : " + txa_CHG_RSN.getText();
    vCtnt += "\r\n\r\n";
    vCtnt += "5. 변경상장일 : " + scwin.dateForm(edt_CHG_LIST_DD.getValue());
    vCtnt += "\r\n\r\n";
    return vCtnt;
};

/**
 * @method
 * @name dateForm
 * @description 년월일 포맷 맞춤 (안내문 작성에서 사용)
 * @param {String} pStr pStr
 * @returns {void}
 * @hidden N
 */
scwin.dateForm = function(pStr) {
    let str = "";
    if (pStr === "") {
        str = "★★★★년" + "★★월" + "★★일";
    } else {
        str = pStr.substring(0, 4) + "년 " + pStr.substring(4, 6) + "월 " + pStr.substring(6, 8) + "일";
    }
    return str;
};

